import React, { createContext, useContext, useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const ThemeContext = createContext(null);

const STORAGE_KEY = 'theme';

const getInicial = () => {
  const salvo = localStorage.getItem(STORAGE_KEY);
  if (salvo === 'dark' || salvo === 'light') return salvo;
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
};

export const ThemeProvider = ({ children }) => {
  const [tema, setTema] = useState(getInicial);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', tema === 'dark');
    localStorage.setItem(STORAGE_KEY, tema);
  }, [tema]);

  const alternarTema = () => setTema((t) => (t === 'dark' ? 'light' : 'dark'));

  return (
    <ThemeContext.Provider value={{ tema, alternarTema }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);

// Ícone disponível em todas as telas pra alternar claro/escuro.
// Páginas ainda não adaptadas pro dark mode simplesmente ignoram a classe "dark" na <html>
// até serem migradas — alternar o tema não quebra o visual delas.
//
// Por padrão fica fixo no canto superior direito (fallback pra páginas sem cabeçalho
// próprio). Em /restaurante/* o RestauranteHeader já renderiza uma cópia `inline` dentro
// da barra superior — nesse caso o fallback fixo se esconde sozinho pra não duplicar
// nem sobrepor o botão do menu (ver RestauranteHeader.jsx). Também escondido na home
// ("/"), a pedido do usuário.
export const ThemeToggle = ({ inline = false }) => {
  const { tema, alternarTema } = useTheme() ?? {};
  const location = useLocation();
  if (!alternarTema) return null;
  if (!inline && (location.pathname.startsWith('/restaurante') || location.pathname === '/')) return null;

  const posicao = inline ? '' : 'fixed top-3 right-3 z-[100]';
  return (
    <button
      onClick={alternarTema}
      title={tema === 'dark' ? 'Mudar para tema claro' : 'Mudar para tema escuro'}
      aria-label="Alternar tema claro/escuro"
      className={`${posicao} w-9 h-9 flex items-center justify-center rounded-full bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] shadow-md hover:scale-105 transition-transform flex-shrink-0`}
    >
      {tema === 'dark' ? (
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
          strokeLinecap="round" strokeLinejoin="round" className="w-4 h-4 text-amber-300">
          <circle cx="12" cy="12" r="4" />
          <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41" />
        </svg>
      ) : (
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
          strokeLinecap="round" strokeLinejoin="round" className="w-4 h-4 text-[#18181B]">
          <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79Z" />
        </svg>
      )}
    </button>
  );
};

const totalTaxaCartao = (comanda.pagamentos ?? []).reduce((acc, p) => acc + (p.taxa_cartao_valor ?? 0), 0);

return (
  <div className={`min-h-screen bg-[#F4F4F5] ${!fechada ? 'pb-44' : 'pb-6'}`}>
    <div className="bg-white border-b border-[#E4E4E7] p-4 sticky top-0 z-10">
      <button onClick={onVoltar} className="flex items-center gap-1 text-sm text-[#71717A] mb-2">
        <Icon name="ArrowLeft" size={16} /> Voltar
      </button>
      <h1 className="text-base font-bold text-[#18181B]">
        #{comanda.numero_comanda ?? comanda.id}{comanda.mesa_id ? ` — Mesa ${comanda.mesas?.numero ?? comanda.mesa_id}` : ''}
      </h1>
      <div className="flex items-center gap-1.5">
        <p className="text-xs text-[#71717A]">{comanda.cliente_mesa_nome} · {comanda.cliente_mesa_telefone}</p>
        <button onClick={() => setMostrarEditarCliente(true)} className="text-[#71717A] hover:text-[#FF441F] flex-shrink-0" title="Editar dados do cliente">
          <Icon name="Pencil" size={12} />
        </button>
      </div>
      {fechada && (
        <p className="text-xs text-blue-700 bg-blue-50 rounded-lg px-2 py-1 mt-2 inline-block">
          Fechada — aguardando pagamento no caixa
        </p>
      )}
      {comanda.tracking_token && (
        <div className="mt-2">
          <button onClick={() => setMostrarQr((v) => !v)}
            className="flex items-center gap-1 text-xs font-bold text-[#FF441F]">
            <Icon name="QrCode" size={14} /> {mostrarQr ? 'Esconder QR' : 'Mostrar QR pro cliente'}
          </button>
          {mostrarQr && (() => {
            const urls = getAcompanharUrls(comanda.tracking_token);
            const urlAtiva = qrModo === 'local' && urls.lan ? urls.lan : urls.principal;
            return (
              <div className="mt-2">
                {urls.lan && (
                  <div className="flex gap-2 mb-2">
                    <button onClick={() => setQrModo('online')}
                      className={`px-3 py-1 rounded-lg text-[10px] font-bold ${qrModo === 'online' ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] text-[#71717A]'}`}>
                      ONLINE
                    </button>
                    <button onClick={() => setQrModo('local')}
                      className={`px-3 py-1 rounded-lg text-[10px] font-bold ${qrModo === 'local' ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] text-[#71717A]'}`}>
                      LOCAL
                    </button>
                  </div>
                )}
                <div className="bg-white border border-[#E4E4E7] rounded-xl p-3 inline-flex flex-col items-center gap-1">
                  <img
                    src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(urlAtiva)}`}
                    alt="QR de acompanhamento" width={150} height={150}
                  />
                  <p className="text-[10px] text-[#71717A]">Cliente escaneia pra acompanhar o preparo</p>
                </div>
              </div>
            );
          })()}
        </div>
      )}
    </div>

    <div className="p-4 space-y-2">
      {(comanda.itens ?? []).map((item) => (
        <div key={item.id} className="bg-white rounded-xl border border-[#E4E4E7] p-3">
          <div className="flex justify-between items-center gap-3">
            <div className="flex items-center gap-3 min-w-0">
              <div className="w-10 h-10 rounded-lg overflow-hidden bg-[#F4F4F5] flex-shrink-0">

